local function Normalize(name)
    return tostring(name):lower():gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
end

-- Swaps the Classic entries of the shared catalogs for Forever's data.
function ForeverCatalog:Apply(data)
    if self.applied or not data then
        return
    end
    self.applied = true
    if data.TrainerCatalog and data.TrainerCatalog.trainers then
        data.TrainerCatalog.trainers.classic = self.trainers
    end
    if data.ExpansionGuideCatalog and data.ExpansionGuideCatalog.byExpansion then
        data.ExpansionGuideCatalog.byExpansion.classic = { fish = self.fish, pools = self.pools, lures = self.lures }
    end
    if data.CollectibleCatalog and data.CollectibleCatalog.byExpansion then
        data.CollectibleCatalog.byExpansion.classic = self.collectibles
    end
    local fishCatalog = data.FishCatalog
    if fishCatalog and fishCatalog.byID and fishCatalog.byName then
        for itemID, name in pairs(self.fishIDs) do
            if not fishCatalog.byID[itemID] then
                fishCatalog.byID[itemID] = { name = name, expansion = "classic" }
            end
            fishCatalog.byName[Normalize(name)] = fishCatalog.byName[Normalize(name)] or itemID
        end
    end
    local poolCatalog = data.PoolCatalog
    if poolCatalog and poolCatalog.byObjectID and poolCatalog.byName then
        for objectID, name in pairs(self.poolIDs) do
            if not poolCatalog.byObjectID[objectID] then
                poolCatalog.byObjectID[objectID] = { name = name, expansion = "classic", expansions = { classic = true } }
            end
            poolCatalog.byName[Normalize(name)] = poolCatalog.byName[Normalize(name)] or objectID
        end
    end
end

AvidAngler.Data.ForeverCatalog = ForeverCatalog

if AvidAngler.IsForeverClient and AvidAngler:IsForeverClient() then
    ForeverCatalog:Apply(AvidAngler.Data)
end
